        return manifestArg;
    const baseDir = path.join(templatesBase, 'manifests');
    const defaultPath = path.join(baseDir, `${resolvedAgent}.json`);
    if (argsProfile === 'minimal') {
        const minimal = path.join(baseDir, `${resolvedAgent}-min.json`);
